html:
{%- set is_receipt = doc.request_type == "Receipt" -%}
{%- set company = frappe.db.get_value("Company", doc.company, ["company_name", "tax_id", "phone_no", "email"], as_dict=True) -%}
{%- set approved = doc.status in ("Approved", "Posted") -%}
<style>
	.tv { font-size: 12px; color: #1f2933; position: relative; }
	.tv-head { display: table; width: 100%; border-bottom: 2px solid #1f2933; padding-bottom: 10px; }
	.tv-head > div { display: table-cell; vertical-align: bottom; }
	.tv-school { font-size: 17px; font-weight: 700; }
	.tv-muted { color: #6b7280; font-size: 11px; }
	.tv-title { text-align: right; }
	.tv-title .en { font-size: 18px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
	.tv-title .ar { font-size: 18px; font-weight: 700; direction: rtl; }
	.tv-meta { width: 100%; margin: 14px 0; border-collapse: collapse; }
	.tv-meta td { padding: 6px 8px; border: 1px solid #d5d9de; vertical-align: top; }
	.tv-meta .lbl { width: 22%; background: #f5f6f8; color: #4b5563; font-size: 11px; }
	.tv-meta .lbl span { display: block; direction: rtl; }
	.tv-amount { margin: 14px 0; padding: 12px 14px; border: 2px solid #1f2933; display: table; width: 100%; }
	.tv-amount > div { display: table-cell; vertical-align: middle; }
	.tv-amount .fig { font-size: 22px; font-weight: 700; text-align: right; white-space: nowrap; }
	.tv-words { font-style: italic; }
	.tv-sign { width: 100%; margin-top: 48px; border-collapse: separate; border-spacing: 18px 0; }
	.tv-sign td { width: 33%; border-top: 1px solid #1f2933; padding-top: 6px; text-align: center; font-size: 11px; vertical-align: top; }
	.tv-sign .ar { direction: rtl; display: block; color: #6b7280; }
	.tv-foot { margin-top: 26px; font-size: 10px; color: #6b7280; border-top: 1px dashed #d5d9de; padding-top: 6px; }
	.tv-mark { position: absolute; top: 38%; left: 8%; right: 8%; text-align: center; font-size: 54px; font-weight: 700;
		color: rgba(197, 48, 48, .13); transform: rotate(-18deg); letter-spacing: .08em; }
</style>
<div class="tv">
	{%- if not approved %}<div class="tv-mark">{{ _("NOT APPROVED") }}</div>{% endif %}
	<div class="tv-head">
		<div>
			<div class="tv-school">{{ company.company_name }}</div>
			<div class="tv-muted">
				{%- if company.tax_id %}TRN {{ company.tax_id }} · {% endif -%}
				{%- if company.phone_no %}{{ company.phone_no }} · {% endif -%}
				{{ company.email or "" }}
			</div>
		</div>
		<div class="tv-title">
			<div class="en">{{ _("Receipt Voucher") if is_receipt else _("Payment Voucher") }}</div>
			<div class="ar">{{ "سند قبض" if is_receipt else "سند صرف" }}</div>
		</div>
	</div>

	<table class="tv-meta">
		<tr>
			<td class="lbl">{{ _("Voucher No") }}<span>رقم السند</span></td><td><b>{{ doc.name }}</b></td>
			<td class="lbl">{{ _("Date") }}<span>التاريخ</span></td><td>{{ doc.get_formatted("posting_date") }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("Received From") if is_receipt else _("Paid To") }}<span>{{ "استلمنا من" if is_receipt else "صرف إلى" }}</span></td>
			<td colspan="3"><b>{{ doc.party_name }}</b> <span class="tv-muted">({{ _(doc.party_type) }}{% if doc.party != doc.party_name %} · {{ doc.party }}{% endif %})</span></td>
		</tr>
		<tr>
			<td class="lbl">{{ _("Mode of Payment") }}<span>طريقة الدفع</span></td><td>{{ doc.mode_of_payment }}</td>
			<td class="lbl">{{ _("Cash / Bank Account") }}<span>الحساب</span></td><td>{{ doc.account }}</td>
		</tr>
		{%- if doc.reference_no %}
		<tr>
			<td class="lbl">{{ _("Cheque / Reference No") }}<span>رقم الشيك / المرجع</span></td><td>{{ doc.reference_no }}</td>
			<td class="lbl">{{ _("Cheque / Reference Date") }}<span>تاريخ الشيك</span></td><td>{{ doc.get_formatted("reference_date") }}</td>
		</tr>
		{%- endif %}
		{%- if doc.against_invoice %}
		<tr>
			<td class="lbl">{{ _("Against Invoice") }}<span>مقابل فاتورة</span></td><td colspan="3">{{ doc.against_doctype }} {{ doc.against_invoice }}</td>
		</tr>
		{%- endif %}
		<tr>
			<td class="lbl">{{ _("Being") }}<span>وذلك عن</span></td><td colspan="3">{{ doc.purpose }}</td>
		</tr>
	</table>

	<div class="tv-amount">
		<div class="tv-words">{{ frappe.utils.money_in_words(doc.amount, doc.currency) }}</div>
		<div class="fig">{{ doc.get_formatted("amount") }}</div>
	</div>

	<table class="tv-sign">
		<tr>
			<td>{{ _("Prepared by") }}<span class="ar">أعدّه</span><b>{{ frappe.db.get_value("User", doc.requested_by, "full_name") or "" }}</b></td>
			<td>{{ _("Approved by") }}<span class="ar">اعتمده</span><b>{{ frappe.db.get_value("User", doc.approved_by, "full_name") or "" }}</b></td>
			<td>{{ _("Received by") if is_receipt else _("Receiver's signature") }}<span class="ar">{{ "المستلم" if is_receipt else "توقيع المستلم" }}</span></td>
		</tr>
	</table>

	<div class="tv-foot">
		{{ _("Status") }}: {{ _(doc.status) }}
		{%- if doc.payment_entry %} · {{ _("Payment Entry") }} {{ doc.payment_entry }} ({{ _(doc.payment_entry_status or "") }}){% endif %}
		{%- if doc.approved_on %} · {{ _("Approved on") }} {{ doc.get_formatted("approved_on") }}{% endif %}
	</div>
</div>
